        {/* NEW SHARE SECTION */}
        <div className="flex flex-col items-center pt-6 mt-6 border-t border-slate-200 dark:border-slate-800">
             <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 opacity-80">
