import { GoogleGenAI, Type, Schema } from "@google/genai";
import { StoryData, StoryParams, AspectRatio, StoryPage } from "../types";
import { SYSTEM_INSTRUCTION, ART_STYLE_OPTIONS } from "../constants";

// Helper to get client with key
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found. Please check your environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

const BATCH_SIZE = 20;

// Helper to expand art style name to full prompt if needed
export const getArtStylePrompt = (styleName: string): string => {
    const styleOption = ART_STYLE_OPTIONS.find(s => s.label === styleName);
    if (styleOption?.isReal) {
        return "Ultra photorealistic, real humans, cinematic lighting, natural skin texture, no cartoon, no illustration";
    }
    if (styleName === "Educational Line Cartoon") {
        return "simple flat line illustration, white background, clean black outlines, minimal flat colors, educational cartoon style, whiteboard illustration, no 3D, no shadows, no textures, simple characters, expressive faces, child-friendly, educational visual, vector-style drawing, no text, no watermark";
    }
    return `${styleName} illustration style, high quality, children friendly`;
};

export class StoryGenerator {
  private isPaused = false;
  private resumeResolver: (() => void) | null = null;
  private ai = getClient();

  public pause() {
    this.isPaused = true;
  }

  public resume() {
    this.isPaused = false;
    if (this.resumeResolver) {
      this.resumeResolver();
      this.resumeResolver = null;
    }
  }

  private async checkPause() {
    if (this.isPaused) {
      await new Promise<void>((resolve) => {
        this.resumeResolver = resolve;
      });
    }
  }

  public async generate(
    params: StoryParams, 
    onProgress: (progress: number, message: string) => void
  ): Promise<StoryData> {
    const totalPages = params.pageCount;

    // 1. Initial Batch
    onProgress(10, "Designing characters and plot...");
    await this.checkPause();

    const initialPageCount = Math.min(totalPages, BATCH_SIZE);

    // Sawan Language & Dialect Logic
    const languageConfig = params.language === 'Arabic' 
      ? { language: "Arabic", dialect: params.dialect || "Egyptian Arabic" }
      : { language: "English", dialect: "Standard American English" };

    // Determine the style prompt part
    const expandedArtStyle = getArtStylePrompt(params.artStyle);

    // Strict prompt based on the user's setup requirements
    const prompt = `
      Create a children's story based on the following inputs:
      1. Story Idea: ${params.idea}
      2. Language & Dialect:
         - Write the story in ${languageConfig.language}.
         - Use ${languageConfig.dialect} naturally.
         - Avoid formal language (MSA) if a dialect is specified; use local expressions suitable for children.
      3. Age Group: ${params.ageGroup}
      4. Length: ${initialPageCount} pages ${totalPages > BATCH_SIZE ? `(Part 1 of ${totalPages})` : ''}
      5. Art Style: ${expandedArtStyle}

      Follow all quality rules and strict JSON output format defined in the system instructions.
      Ensure you generate exactly ${initialPageCount} pages in this batch.
    `;

    const pageSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        page: { type: Type.INTEGER },
        text: { type: Type.STRING },
        image_prompt: { type: Type.STRING },
      },
      required: ["page", "text", "image_prompt"]
    };

    // Strict schema matching the user's "STRICT OUTPUT FORMAT"
    const initialSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        story_info: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            language: { type: Type.STRING },
            age_group: { type: Type.STRING },
            art_style: { type: Type.STRING },
          },
          required: ["title", "language", "age_group", "art_style"]
        },
        characters: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              personality: { type: Type.STRING },
              age: { type: Type.STRING },
              gender: { type: Type.STRING },
            },
            required: ["name", "description", "personality", "age", "gender"]
          }
        },
        pages: {
          type: Type.ARRAY,
          items: pageSchema
        }
      },
      required: ["story_info", "characters", "pages"]
    };

    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: 'application/json',
        responseSchema: initialSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    let storyData: StoryData;
    try {
      const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsed = JSON.parse(cleanedText);

      // We manually inject aspect_ratio because the AI Strict JSON doesn't include it, but our UI needs it
      storyData = {
        ...parsed,
        story_info: {
          ...parsed.story_info,
          aspect_ratio: params.aspectRatio,
          art_style: params.artStyle,
          dialect: params.dialect // Injected to persist dialect choice
        }
      };

    } catch (e) {
      console.error("Failed to parse story JSON", text);
      throw new Error("Failed to generate valid story structure.");
    }

    // Update progress based on initial batch
    const initialProgress = Math.min(100, Math.round((initialPageCount / totalPages) * 100));
    onProgress(initialProgress, `Generated ${initialPageCount} of ${totalPages} pages...`);

    // 2. Subsequent Batches Loop
    if (totalPages > BATCH_SIZE) {
       let currentPage = storyData.pages.length + 1;

       while (currentPage <= totalPages) {
           await this.checkPause();

           // --- Chapter Logic (Every 50 pages) ---
           const generatedCount = storyData.pages.length;
           if (generatedCount > 0 && generatedCount % 50 === 0) {
               const chapterNum = (generatedCount / 50) + 1;

               const chapterPage: StoryPage = {
                   page: currentPage,
                   text: `Chapter ${chapterNum}`,
                   image_prompt: `A decorative title page for Chapter ${chapterNum} of the story "${storyData.story_info.title}". ${expandedArtStyle}, elegant, magical typography, detailed background elements matching the story theme.`
               };

               storyData.pages.push(chapterPage);
               currentPage++;

               onProgress(
                   Math.round(((currentPage - 1) / totalPages) * 100), 
                   `Starting Chapter ${chapterNum}...`
               );

               // If adding the chapter page reached the total, stop here
               if (currentPage > totalPages) break;
           }
           // --------------------------------------

           const remaining = totalPages - currentPage + 1;
           const currentBatchSize = Math.min(remaining, BATCH_SIZE);
           const endPage = currentPage + currentBatchSize - 1;

           onProgress(
             Math.round(((currentPage - 1) / totalPages) * 100), 
             `Generating pages ${currentPage} to ${endPage}...`
           );

           const continuationPrompt = `
             You are continuing a children's story.

             Story Context:
             - Title: ${storyData.story_info.title}
             - Characters: ${storyData.characters.map(c => c.name).join(', ')}
             - Style: ${expandedArtStyle}
             - Language: ${languageConfig.language} (${languageConfig.dialect})
             - Last Page (${currentPage-1}): "${storyData.pages[storyData.pages.length - 1].text}"

             TASK: Generate pages ${currentPage} to ${endPage}.

             RULES:
             1. Keep strict continuity in plot and character behavior.
             2. Maintain the same art style descriptions for image prompts.
             3. Output a valid JSON object with a "pages" array.
             4. Continue using ${languageConfig.dialect} naturally.
           `;

           const nextResponse = await this.ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: continuationPrompt,
              config: {
                  responseMimeType: 'application/json',
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          pages: {
                              type: Type.ARRAY,
                              items: pageSchema
                          }
                      }
                  }
              }
           });

           const nextText = nextResponse.text;
           if (nextText) {
               try {
                  const cleanedNextText = nextText.replace(/```json/g, '').replace(/```/g, '').trim();
                  const nextData = JSON.parse(cleanedNextText);
                  if (nextData.pages && Array.isArray(nextData.pages)) {
                      storyData.pages = [...storyData.pages, ...nextData.pages];
                  }
               } catch (e) {
                   console.error(`Failed to parse batch ${currentPage}-${endPage}`, e);
                   break;
               }
           }

           currentPage += currentBatchSize;
           const currentProgress = Math.min(100, Math.round(((currentPage - 1) / totalPages) * 100));
           onProgress(currentProgress, `Completed ${currentPage - 1} pages...`);
       }
    }

    onProgress(100, "Finalizing story...");
    return storyData;
  }
}

export const generateIllustration = async (prompt: string, aspectRatio: AspectRatio): Promise<string> => {
  const ai = getClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: prompt }] },
    config: { imageConfig: { aspectRatio: aspectRatio } }
  });

  const candidates = response.candidates;
  if (candidates?.[0]?.content?.parts) {
      for (const part of candidates[0].content.parts) {
          if (part.inlineData?.data) return part.inlineData.data;
      }
  }
  throw new Error("No image generated.");
};

export const regeneratePrompt = async (currentPrompt: string): Promise<string> => {
    const ai = getClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Rewrite the following image prompt to change the camera angle or composition slightly, while keeping the subject and style exactly the same. Original: "${currentPrompt}". Return ONLY the new prompt text.`,
    });
    return response.text?.trim() || currentPrompt;
};

export const generateNameMeaning = async (name: string, language: 'English' | 'Arabic') => {
  const ai = getClient();
  const isAr = language === 'Arabic';

  const prompt = isAr 
    ? `اشرح معنى الاسم "${name}" لطفل عمره من 5 إلى 12 سنة.
       المطلوب: إخراج كائن JSON يحتوي على:
       - meaning: معنى الاسم بشكل لطيف
       - origin: أصل الاسم (عربي، فارسي، إلخ)
       - traits: 3 صفات إيجابية لحامل الاسم
       استخدم جمل قصيرة وبسيطة ولطيفة للأطفال.
       ممنوع ذكر أي معلومات دينية معقدة أو حساسة.`
    : `Explain the meaning of the name "${name}" for a child aged 5–12.
       Output a JSON object with:
       - meaning: Gentle meaning of the name
       - origin: Origin of the name
       - traits: 3 positive traits
       Use short, friendly, child-safe sentences.
       Do NOT include sensitive or religious content.`;

  const schema: Schema = {
    type: Type.OBJECT,
    properties: {
      meaning: { type: Type.STRING },
      origin: { type: Type.STRING },
      traits: { type: Type.STRING },
    },
    required: ["meaning", "origin", "traits"]
  };

  const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
          responseMimeType: 'application/json',
          responseSchema: schema
      }
  });

  try {
      const text = response.text;
      if (!text) throw new Error("No response");
      return JSON.parse(text.replace(/```json/g, '').replace(/```/g, '').trim());
  } catch (e) {
      console.error("Name Meaning Parse Error", e);
      return {
          meaning: isAr ? "اسم جميل ومميز" : "A beautiful and unique name",
          origin: isAr ? "غير معروف" : "Unknown",
          traits: isAr ? "لطيف، ذكي، محبوب" : "Kind, smart, loved"
      };
  }
};

import React, { useState, useEffect } from 'react';
import { Sparkles, Globe, Heart, Book, ArrowLeft, ArrowRight, Wand2, Volume2, PlayCircle } from 'lucide-react';
import { generateNameMeaning } from '../services/gemini';

interface Props {
  language: 'English' | 'Arabic';
  onBack: () => void;
}

export const NameMeaning: React.FC<Props> = ({ language, onBack }) => {
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{meaning: string, origin: string, traits: string} | null>(null);
  const [voiceGender, setVoiceGender] = useState<'female' | 'male'>('female');
  const [availableVoices, setAvailableVoices] = useState<SpeechSynthesisVoice[]>([]);

  // Robust voice loading logic
  useEffect(() => {
    const loadVoices = () => {
      const voices = window.speechSynthesis.getVoices();
      if (voices.length > 0) {
        setAvailableVoices(voices);
      }
    };

    loadVoices();

    // Chrome loads voices asynchronously
    if (window.speechSynthesis.onvoiceschanged !== undefined) {
      window.speechSynthesis.onvoiceschanged = loadVoices;
    }

    return () => { window.speechSynthesis.onvoiceschanged = null; };
  }, []);

  const isAr = language === 'Arabic';
  const t = {
    title: isAr ? "📛 معنى اسمك" : "📛 Name Meaning",
    desc: isAr ? "اكتب اسمك واكتشف ماذا يعني!" : "Type your name and discover what it means!",
    placeholder: isAr ? "اكتب اسمك هنا" : "Type your name here",
    btn: isAr ? "✨ اعرف معنى اسمك" : "✨ Discover your name meaning",
    meaning: isAr ? "📘 المعنى" : "📘 Meaning",
    origin: isAr ? "🌍 الأصل" : "🌍 Origin",
    traits: isAr ? "💖 الصفات" : "💖 Traits",
    loading: isAr ? "جاري اكتشاف معنى اسمك..." : "Discovering your name meaning...",
    back: isAr ? "رجوع" : "Back",
    subtitle: isAr ? "رحلة ممتعة في عالم الأسماء" : "A fun journey into names",
    voiceSelect: isAr ? "🎧 اختر الصوت:" : "🎧 Voice:",
    male: isAr ? "👨 صوت رجل" : "👨 Male",
    female: isAr ? "👩 صوت سيدة" : "👩 Female",
    readAll: isAr ? "🔊 قراءة الملخص" : "🔊 Read Summary",
    voiceError: isAr ? "⚠️ الصوت العربي غير مدعوم على جهازك حاليًا" : "⚠️ Voice not supported on this device.",
  };

  const handleSearch = async () => {
    if (!name.trim()) return;
    setLoading(true);
    setResult(null);
    try {
        const data = await generateNameMeaning(name, language);
        setResult(data);
    } catch (e) {
        console.error(e);
        // Fallback handled in service or could be added here
    } finally {
        setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const handleSpeak = (text: string) => {
    if (!text) return;

    window.speechSynthesis.cancel();

    // Get voices from state or direct call if state empty (fallback)
    const voices = availableVoices.length > 0 ? availableVoices : window.speechSynthesis.getVoices();

    const targetLang = isAr ? "ar" : "en";

    // Filter matching language voices
    const langVoices = voices.filter(v => 
        v.lang.toLowerCase().startsWith(targetLang) || 
        v.lang.toLowerCase().includes(isAr ? "arabic" : "english")
    );

    // If Arabic requested but no voices found
    if (isAr && langVoices.length === 0) {
        alert(t.voiceError);
        return;
    }

    let preferredVoice = undefined;

    if (langVoices.length > 0) {
        if (voiceGender === 'female') {
            preferredVoice = langVoices.find(v => 
                v.name.toLowerCase().includes("female") || 
                v.name.includes("Samantha") || 
                v.name.includes("Zira") || 
                v.name.includes("Google") // Google voices often female default
            );
        } else {
            preferredVoice = langVoices.find(v => 
                v.name.toLowerCase().includes("male") || 
                v.name.includes("David") || 
                v.name.includes("Maged") || 
                v.name.includes("Tarik")
            );
        }

        // Fallback to first available matching language voice
        if (!preferredVoice) {
            preferredVoice = langVoices[0];
        }
    }

    const utter = new SpeechSynthesisUtterance(text);
    utter.lang = isAr ? "ar-SA" : "en-US";
    utter.rate = 0.9; // Slightly slower for clarity/kids
    utter.pitch = 1;

    if (preferredVoice) {
      utter.voice = preferredVoice;
      utter.lang = preferredVoice.lang;
    }

    window.speechSynthesis.speak(utter);
  };

  const handleReadAll = () => {
      if (!result) return;
      const fullText = isAr 
        ? `الاسم: ${name}. المعنى: ${result.meaning}. الأصل: ${result.origin}. الصفات: ${result.traits}.`
        : `Name: ${name}. Meaning: ${result.meaning}. Origin: ${result.origin}. Traits: ${result.traits}.`;
      handleSpeak(fullText);
  };

  return (
    <div className="w-full max-w-4xl mx-auto p-4 animate-fade-in flex flex-col items-center min-h-[500px]">

        {/* Styled Hero Header */}
        <div 
            className="relative w-full rounded-[18px] overflow-hidden bg-cover bg-center md:bg-bottom py-16 md:py-20 px-4 text-center mb-8 shadow-2xl border border-slate-700/50"
            style={{ 
                backgroundImage: "linear-gradient(rgba(10,15,30,0.65), rgba(10,15,30,0.85)), url('https://png.pngtree.com/thumb_back/fh260/background/20241231/pngtree-amusement-park-image_16505595.jpg')" 
            }}
        >
            {/* Glow Overlay */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.08),transparent_60%)] pointer-events-none"></div>

            <h1 className="relative z-10 text-3xl md:text-5xl font-heading font-bold text-white mb-4 flex items-center justify-center gap-4">
                <span className="text-sky-400 drop-shadow-md">📛</span>
                <span className="drop-shadow-md">{t.title}</span>
            </h1>
