        </div>

        {/* Action Button or Generation Box */}
        <div className="pt-4">

            {/* Only Prompts Toggle */}
            {!isLoading && (
            <div className="flex items-center gap-3 mb-4 p-3 bg-slate-100 dark:bg-slate-800/50 rounded-xl border border-slate-200 dark:border-slate-700">
                <input 
                    type="checkbox" 
                    id="onlyPrompts"
                    checked={params.onlyPrompts || false}
                    onChange={(e) => handleChange('onlyPrompts', e.target.checked)}
                    className="w-5 h-5 rounded border-gray-300 text-brand-600 focus:ring-brand-500 cursor-pointer"
                />
                <label htmlFor="onlyPrompts" className="text-sm font-bold text-gray-700 dark:text-gray-300 cursor-pointer select-none">
                    {params.language === 'Arabic' ? 'توليد الوصف فقط (بدون صور)' : 'Only generate prompts (no images)'}
                </label>
            </div>
            )}

            {!isLoading ? (
                <button
                    onClick={onSubmit}
                    disabled={!params.idea.trim() || isTooShort}
                    className={`w-full py-6 rounded-2xl text-2xl font-heading font-bold text-white shadow-xl transition-all transform hover:-translate-y-1 ${
                        !params.idea.trim() || isTooShort
                        ? 'bg-gray-300 dark:bg-slate-700 cursor-not-allowed'
                        : 'bg-gradient-to-r from-brand-500 to-brand-600 hover:shadow-2xl hover:scale-[1.01]'
