      `🎉 ${r.years} سنة\n` +
      `📆 ${r.months} شهر\n` +
      `📅 ${r.days} يوم\n` +
      `🗓️ ${r.weeks} أسبوع\n` +
      `⏰ ${r.hours} ساعة\n` +
      `⏱️ ${r.seconds} ثانية`,

    lucky: (n: number) => `✨ رقم حظك هو ${n}`,
    msgs: [
        "ابتسم 😊 يومك جميل",
        "أنت شجاع 💪",
