    const minutes = Math.round(totalSeconds / 60);
    if (minutes < 60) {
        return isAr ? `${minutes} دقيقة` : `${minutes} minutes`;
    }
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;

    if (isAr) {
        return `${hours} ساعة${mins ? ` و ${mins} دقيقة` : ''}`;
    }
    return `${hours} hr${mins ? ` ${mins} min` : ''}`;
